'use strict';

export var scriptProperties = createScriptProperties()
	// Whether you want a 24h or 12h style format
	.addCheckbox({
		name: 'use24hFormat',
		label: 'ui_editor_properties_use_24h_format',
		value: true
	})
	// Whether you want to see the seconds or not
	.addCheckbox({
		name: 'showSeconds',
		label: 'ui_editor_properties_show_seconds',
		value: false
	})
	// This will be used to separate each element
	.addText({
		name: 'delimiter',
		label: 'ui_editor_properties_delimiter',
		value: ':'
	})
	.finish();

/**
 * @param {String} value (for property 'text')
 */
export function update(value) {
	let time = new Date();
	var hours = time.getHours();
	if (!scriptProperties.use24hFormat) {
		hours %= 12;
		if (hours == 0) {
			hours = 12;
		}
	}
	hours = ("00" + hours).slice(-2);
	let minutes = ("00" + time.getMinutes()).slice(-2);
	value = hours + scriptProperties.delimiter + minutes;
	if (scriptProperties.showSeconds) {
		let seconds = ("00" + time.getSeconds()).slice(-2);
		value += scriptProperties.delimiter + seconds;
	}
	return value;
}

曲线透明度.script:
'use strict';

import * as WEMath from 'WEMath';

export var scriptProperties = createScriptProperties()
    .addSlider({
        name: 'timer',
        label: 'Fade out timer淡出计时',
        value: 2,
        min: 0,
        max: 10,
        integer: false
    })
    .addSlider({
        name: 'fadeInDur',
        label: 'Fade in duration淡入时长',
        value: 0.5,
        min: 0,
        max: 2,
        integer: false
    })
    .addSlider({
        name: 'fadeOutDur',
        label: 'Fade out duration淡出时长',
        value: 0.5,
        min: 0,
        max: 2,
        integer: false
    })
    .finish();

let audioBuffer = engine.registerAudioBuffers(16);
let changeTime, initValue, timePassed = 0, state, oldState, changedState = false;

export function update(value) {
    state = !!audioBuffer.average.reduce((a, b) => a + b);
    if (oldState != state) {
        changeTime = Date.now();
        changedState = true;
    }
    timePassed = Date.now() - changeTime;
    if (changedState && state) {
        value = WEMath.mix(value, initValue, engine.frametime / scriptProperties.fadeInDur);
        changedState = value != initValue;
    } else if (changedState && !state) {
        let timer = timePassed * 0.001 - scriptProperties.timer;
        if (timer > 0) value = WEMath.mix(value, 0, engine.frametime / scriptProperties.fadeOutDur);
        changedState = value != 0;
    }
    oldState = state;
    return value;
}

export function init(value) {
    changeTime = Date.now();
    initValue = value;
    oldState = !!audioBuffer.average.reduce((a, b) => a + b);
    return oldState ? initValue : 0;
}

