'use strict';
shared.biao = false;
const months = [
	'January', 'February', 'March', 'April', 'May', 'June',
	'July', 'August', 'September', 'October', 'November', 'December'
];

export function update(value) {
	let today = new Date();
	let displayDate;

	if (shared.biao == false) {
		displayDate = today;
		let jsDay = today.getDay();
		shared.hover = jsDay === 0 ? 7 : jsDay;
	} else {
		let todayWeekday = today.getDay();
		let todayCustom = todayWeekday === 0 ? 7 : todayWeekday;
		let mondayOffset = 1 - todayCustom;
		let mondayDate = new Date(today);
		mondayDate.setDate(today.getDate() + mondayOffset);
		let targetOffset = shared.hover === 7 ? 6 : shared.hover - 1;
		displayDate = new Date(mondayDate);
		displayDate.setDate(mondayDate.getDate() + targetOffset);
	}
	thisScene.getLayer('日期').text = displayDate.getDate();
	thisScene.getLayer('月份').text = months[displayDate.getMonth()];
	// thisScene.getLayer('年').text = displayDate.getFullYear();

	// let isWeekend = (shared.hover == 6 || shared.hover == 7);
	// thisScene.getLayer("日期块").getEffect("周六日").visible = isWeekend;
	// console.log(displayDate.getDate())
	// console.log(months[displayDate.getMonth()])
	return value;
}

