visible.script:
'use strict';

import * as WEMath from 'WEMath';

// 应用启动器停靠栏 v1.5 测试版
// 构建版本 30.10_0222

export var scriptProperties = createScriptProperties()
    .addCheckbox({ name: 'autoHide', label: '自动隐藏停靠栏', value: false })
    .addCheckbox({ name: 'autoHideOverwrite', label: '自动隐藏覆盖 <small>(用于在自动隐藏时更改设置)</small>', value: false })
    .addSlider({ name: 'minScale', label: '图标缩放', value: 0.5, min: 0.1, max: 2, integer: false })
    .addSlider({ name: 'scaleMultiplier', label: '悬停缩放倍数 <small>(图标 %)</small>', value: 1.5, min: 1, max: 3, integer: false })
    .addSlider({ name: 'baseRadius', label: '光标半径', value: 0.5, min: 0, max: 1, integer: false })
    .addSlider({ name: 'spacing', label: '间距 <small>(图标 %)</small>', value: 0.3, min: 0, max: 1, integer: false })
    .addSlider({ name: 'outerSpacing', label: '外边距 <small>(图标 %)</small>', value: 0.3, min: 0, max: 1, integer: false })
    .addSlider({ name: 'edgeThreshold', label: '边缘对齐阈值 <small>(画布 %)</small>', value: 10, min: 0, max: 50, integer: false })

    // 弹跳动画属性
    .addSlider({ name: 'jumpHeight', label: '跳跃高度', value: 72, min: 10, max: 200, integer: true })
    .addSlider({ name: 'bounces', label: '弹跳次数', value: 5, min: 1, max: 10, integer: true })
    .addSlider({ name: 'duration', label: '弹跳持续时间 (秒)', value: 2.5, min: 0.5, max: 5.0, integer: false })

    // 图标数量控制
    .addSlider({ name: 'iconCount', label: '启用图标数量', value: 6, min: 1, max: 32, integer: true })

    // 拖拽功能控制
    .addCheckbox({ name: 'enableDragging', label: '启用图标拖拽 <small>(长按0.25秒后可拖拽)</small>', value: true })

    // 测试启动器控制
    .addCheckbox({ name: 'enableTestLauncher', label: '启用测试启动器 <small>(显示测试模块)</small>', value: false })
.finish();

// 默认图标图层名称（默认长度为32）
let ICON_NAMES = Array.from({ length: 32 }, (_, i) => `Launcher ${i + 1}`);

const EXTENSION_PREFIX = "Launcher &e"; // 扩展前缀（开发中）
const JUMP_HEIGHT = 72;                 // 弹跳跳跃幅度（固定以保持稳定性）
const BOUNCES = 5;                      // 点击后弹跳次数
const DURATION = 2.5;                   // 弹跳总持续时间
const MIN_DISTANCE_FACTOR = 1.125;      // 最大悬停缩放的距离因子
const FADE_SPEED = 12;                // 自动隐藏淡入淡出速度
const HIDE_DELAY = 3.5;                 // 隐藏前的延迟时间
const ICON_SIZE = 128;                  // 基础图标分辨率
const BACKGROUND_BASE_WIDTH = 128;      // 背景图层基础分辨率
const MIN_Y_THRESHOLD = 0.9;            // 强制向下停靠的最大垂直阈值
const USER_RADIUS = { min: 2, max: 8 }; // 内部光标半径映射（用户看到的是0-1）

// --- 拖拽和重新排序支持 --- 拖拽和间隙全局变量
let isAnyHeld = false;
let draggingIndex = -1;    // 被拖拽图标在dockOrder/icons中的索引（拖拽时保持不变）
let dockOrder;
let gapIndex = -1;        // 在*可见*序列中的插入索引（0..N）
let heldIconWorldPos = new Vec3(); // 放置被拖拽图标的当前世界位置（跟随光标）

let icons = [];                         // 缓存的图标图层引用
let bounceTimers = {};                  // 每个图标的弹跳开始时间
let mode = "horizontal";                // '水平' 或 '垂直'
let parent = null;                      // 父图层（停靠栏根）
let spacing = 0;                        // 计算的间距（像素）
let alignment = "bottom";               // 当前对齐字符串
let thresholdY = 0;                     // 计算的Y阈值（像素）
let canvasSize = null;                  // engine.canvasSize缓存
let outerSpacing = 0;                   // 计算的外边距（像素）
let bounceDirection = 1;                // 根据停靠栏侧面为1或-1
let iconHideTimer = 0.0;                // 自动隐藏计时器
let lastParentPos = new Vec3(0, 0, 0);  // 父级移动检查的缓存
let targetHoverScale;

/**
 * 将用户定义的scriptProperties应用到派生的共享值。
 * 当用户更改属性时由引擎调用。
 */
export function applyUserProperties() {
    // 为了清晰起见，一次性获取值
    const minScale = scriptProperties.minScale;
    const baseRadius = scriptProperties.baseRadius;
    const multiplier = scriptProperties.scaleMultiplier;

    // 将用户baseRadius（0-1）映射到内部USER_RADIUS范围
    const userRadius = USER_RADIUS.min + Math.max(0.01, baseRadius) * (USER_RADIUS.max - USER_RADIUS.min);

    // 通过minScale和multiplier缩放的图标半径（限制multiplier效果）
    const scaledRadius = minScale * (userRadius * (Math.min(2, multiplier * 0.66)));

    // 图标像素大小（用于间距、最小距离计算）
    const iconScalePixels = ICON_SIZE * minScale;

    // 导出到shared，以便其他图层/脚本/读取器可以使用它们
    shared.edgeThreshold = scriptProperties.edgeThreshold * 0.01;
    shared.minScale = minScale;
    shared.maxScale = minScale * multiplier;
    shared.radius = scaledRadius * ICON_SIZE;
    shared.minDistance = iconScalePixels * MIN_DISTANCE_FACTOR;

    // 用于布局数学的本地缓存值
    spacing = minScale * (ICON_SIZE * scriptProperties.spacing);
    outerSpacing = minScale * (ICON_SIZE * scriptProperties.outerSpacing);
}

/**
 * 初始化脚本：缓存父级、画布大小、检测扩展图层，
 * 并缓存图标图层引用。同时设置初始共享透明度。
 */
export function init() {
    parent = thisLayer.getParent();        // 父图层引用（停靠栏根）
    canvasSize = engine.canvasSize;       // 缓存画布大小用于阈值计算
    thresholdY = canvasSize.y * Math.min(MIN_Y_THRESHOLD, 1 - (scriptProperties.edgeThreshold * 0.01));

    // 检测场景中的可选扩展启动器并附加它们的名称
    const extensions = detectExtensions();
    if (extensions.length > 0) {
        ICON_NAMES = ICON_NAMES.concat(extensions);
    }

    let savedOrder = null;
    const stored = localStorage.get("dockOrder");
    if (stored) {
        savedOrder = typeof stored === 'string' ? JSON.parse(stored) : stored;
    }

    // 重构顺序：首先是保存的项目（如果它们仍然存在），然后是新项目
    if (savedOrder && Array.isArray(savedOrder) && savedOrder.length > 0) {
        const validSaved = savedOrder.filter(n => ICON_NAMES.indexOf(n) !== -1);
        const newIcons = ICON_NAMES.filter(n => validSaved.indexOf(n) === -1);
        dockOrder = validSaved.concat(newIcons);
    } else {
        dockOrder = ICON_NAMES.slice();
    }

    icons = dockOrder.map(name => thisScene.getLayer(name));

    // 共享停靠栏可见性的默认透明度
    shared.dockAlpha = 1.0;
}

export function update() {
    // 如果停靠栏的父级被隐藏，则无需执行任何操作
    if (!parent.visible) return;

    // 共享光标位置给其他图层以减少光标位置调用
    shared.cursorWorldPosition = input.cursorWorldPosition;

    // 更新对齐方式
    updateAlignmentIfNeeded();

    handleIconDragging();

    // 拖拽图标时平滑淡化悬停缩放
    if (isAnyHeld) {
        targetHoverScale = scriptProperties.minScale; // 有效地禁用缩放
    } else {
        targetHoverScale = scriptProperties.minScale * scriptProperties.scaleMultiplier;
    }

    // 在当前和目标maxScale之间平滑插值
    shared.maxScale += (targetHoverScale - shared.maxScale) * FADE_SPEED * engine.frametime;

    // 拖拽时调整悬停缩放淡化
    // const targetScale = isAnyHeld ? 0.0 : scriptProperties.minScale * scriptProperties.scaleMultiplier;
    // shared.maxScale += (targetScale - shared.maxScale) * HOLD_SCALE_FADE_SPEED * engine.frametime;

    // 收集可见图标及其计算的大小
    const visibleIcons = collectVisibleIconData();

    // 如果没有可见图标，则无需执行任何操作
    if (visibleIcons.length === 0) return;

    // 自动隐藏逻辑调整shared.dockAlpha和iconHideTimer
    autoHideDock();

    // 计算总跨度（图标+间距）以计算图层缩放和偏移
    const totalSize = visibleIcons.reduce((sum, d) => sum + d.size, 0) + Math.max(0, visibleIcons.length - 1) * spacing;
    updateScale(totalSize); // 根据模式和总跨度调整thisLayer.scale

    // 共享完整的停靠栏宽度用于拖放图层优化
    shared.appDockWidth = totalSize;

    // 沿轴定位图标，应用弹跳偏移和每个图标的原点
    layoutIconsWithBounce(totalSize);
}

/**
 * 收集可见图标并计算它们的主轴大小。
 * @returns {Array<{layer: ILayer, size: Number, index: Number, isExtension: Boolean}>}
 */
function collectVisibleIconData() {
    const result = [];

    for (let i = 0; i < icons.length; i++) {
        const icon = icons[i];
        // 提前跳过缺失的图层
        if (!icon) continue;

        // 通过名称检测扩展
        const isExtension = icon.name && icon.name.startsWith(EXTENSION_PREFIX);

        // 普通图标由iconCount属性控制；扩展控制自己的可见性
        if (!isExtension) {
            const enabled = i < scriptProperties.iconCount;
            // 将可见性标志同步到属性以保持编辑器一致性
            if (icon.visible !== enabled) icon.visible = enabled;
            if (!enabled) continue; // 跳过禁用的图标
        } else {
            // 扩展图标：如果它们被设置为不可见，跳过它们（它们管理自己的可见性）
            if (!icon.visible) continue;
        }

        // 确保图标对齐与我们计算的对齐匹配；为每个可见图标设置一次
        if (icon.alignment !== alignment) icon.alignment = alignment;

        // 选择正确的向量（某些扩展可能提供extensionScale）
        const scaleVec = (isExtension && icon.extensionScale) ? icon.extensionScale : icon.size;

        // 计算活动轴中的图标大小（水平使用x，垂直使用y）
        const axis = (mode === "horizontal") ? "x" : "y";
        const iconSize = (mode === "horizontal" ? scaleVec.x : scaleVec.y) * icon.scale[axis];

        result.push({ layer: icon, size: iconSize, index: i, isExtension: isExtension });
    }

    return result;
}

/**
 * 布局图标并应用弹跳偏移。
 * @param {Array} visibleIcons - collectVisibleIconData()返回的数组
 * @param {Number} totalSize - 所有图标大小加间距的总长度
 */
function layoutIconsWithBounce(totalSize) {
    let offset = -totalSize * 0.5;

    // 构建有序列表（排除被拖拽的图标）
    const ordered = [];
    for (let i = 0; i < dockOrder.length; i++) {
        const layer = thisScene.getLayer(dockOrder[i]);
        if (!layer || !layer.visible) continue;
        if (isAnyHeld && i === draggingIndex) continue;

        // 检查是否需要开始弹跳动画
        if (layer.clicked && bounceTimers[i] === undefined) {
            // 特殊处理：如果是扩展图层（以 EXTENSION_PREFIX 开头），不设置弹跳计时器
            if (layer.name && layer.name.startsWith(EXTENSION_PREFIX)) {
                // 直接重置 clicked 状态，不触发弹跳
                layer.clicked = false;
            } else {
                // 普通图标：设置弹跳计时器并重置 clicked 状态
                bounceTimers[i] = engine.runtime;
                layer.clicked = false; // 重置 clicked 状态，防止无限循环弹跳
            }
        }

        const s = layer.scale;
        const sizePx = (mode === 'horizontal') ? layer.size.x * s.x : layer.size.y * s.y;
        ordered.push({ i, layer, size: sizePx });
    }

    for (let i = 0; i <= ordered.length; i++) {
        if (i === gapIndex) {
            // 被拖拽图标的虚拟间隙
            if (isAnyHeld && draggingIndex !== -1) {
                const held = thisScene.getLayer(dockOrder[draggingIndex]);
                if (held) {
                    const s = held.scale;
                    const gSize = (mode === 'horizontal') ? held.size.x * s.x : held.size.y * s.y;
                    offset += gSize + spacing;
                }
            }
        }

        if (i < ordered.length) {
            const { layer, size, i: dockIdx } = ordered[i];
            const bounceOffset = computeBounceOffset(dockIdx);
            let origin;
            if (mode === 'horizontal') {
                origin = new Vec3(thisLayer.origin.x + offset + size * 0.5, thisLayer.origin.y + outerSpacing * bounceDirection + bounceOffset, 0);
                offset += size + spacing;
            } else {
                origin = new Vec3(thisLayer.origin.x + outerSpacing * bounceDirection + bounceOffset, thisLayer.origin.y + offset + size * 0.5, 0);
                offset += size + spacing;
            }
            layer.origin = origin;
        }
    }

    // 放置跟随光标的被拖拽图标
    if (isAnyHeld && draggingIndex !== -1) {
        const held = thisScene.getLayer(dockOrder[draggingIndex]);
        if (held) {
            const bounceOffset = computeBounceOffset(draggingIndex);
            const o = new Vec3(
                thisLayer.origin.x + heldIconWorldPos.x,
                thisLayer.origin.y + heldIconWorldPos.y,
                0
            );
            if (mode === 'horizontal')
                o.y = thisLayer.origin.y + outerSpacing * bounceDirection + bounceOffset;
            else
                o.x = thisLayer.origin.x + outerSpacing * bounceDirection + bounceOffset;
            held.origin = o;
        }
    }
}

/**
 * 计算单个图标索引的弹跳偏移。
 * @param {Number} iconIndex
 * @returns {Number} bounceOffset (像素)
 */
function computeBounceOffset(iconIndex) {
    if (bounceTimers[iconIndex] === undefined) return 0;

    // 特殊处理：如果是扩展图层（以 EXTENSION_PREFIX 开头），直接返回 0（禁用弹跳）
    if (iconIndex < dockOrder.length) {
        const layerName = dockOrder[iconIndex];
        const layer = thisScene.getLayer(layerName);
        if (layer && layer.name && layer.name.startsWith(EXTENSION_PREFIX)) {
            return 0;
        }
    }

    // 使用用户定义的属性，回退到常量
    const jumpHeight = scriptProperties.jumpHeight || JUMP_HEIGHT;
    const bounces = scriptProperties.bounces || BOUNCES;
    const duration = scriptProperties.duration || DURATION;

    const t = (engine.runtime - bounceTimers[iconIndex]) / duration;
    if (t >= 1) {
        // 弹跳结束；清理
        delete bounceTimers[iconIndex];
        return 0;
    }

    // 跨弹跳周期的进度
    const progress = t * bounces;
    const bounceIndex = Math.floor(progress);
    const localT = progress - bounceIndex;
    const decay = 1 - bounceIndex / bounces;
    return Math.sin(localT * Math.PI) * jumpHeight * decay * bounceDirection;
}

/**
 * 仅在父级自上一帧移动时更新对齐方式。
 * 缓存lastParentPos以避免每帧的冗余计算。
 */
function updateAlignmentIfNeeded() {
    const currentPos = parent.origin;

    // 快速Vec3相等性检查（Vec3对象不是原始类型；逐分量比较）
    if (currentPos.x === lastParentPos.x && currentPos.y === lastParentPos.y && currentPos.z === lastParentPos.z) {
        // 父级没有移动，跳过昂贵的阈值数学计算
        return;
    }

    // 缓存当前父级位置用于下一帧
    lastParentPos = new Vec3(currentPos.x, currentPos.y, currentPos.z);

    // 基于画布大小和用户edgeThreshold重新计算阈值（shared.edgeThreshold由applyUserProperties更新）
    const thresholdX = canvasSize.x * shared.edgeThreshold;
    thresholdY = canvasSize.y * Math.min(MIN_Y_THRESHOLD, 1 - shared.edgeThreshold);

    // 根据到画布边缘的距离决定布局模式和对齐方式
    if (currentPos.x <= thresholdX) {
        mode = "vertical";
        alignment = "left";
        bounceDirection = 1;
    } else if (currentPos.x >= canvasSize.x - thresholdX) {
        mode = "vertical";
        alignment = "right";
        bounceDirection = -1;
    } else if (currentPos.y <= thresholdY) {
        mode = "horizontal";
        alignment = "bottom";
        bounceDirection = 1;
    } else {
        mode = "horizontal";
        alignment = "top";
        bounceDirection = -1;
    }

    // 将选择的对齐方式暴露给其他脚本/图层
    shared.appDockAlignment = alignment;
    thisLayer.alignment = alignment;
}

/**
 * 自动隐藏停靠栏逻辑。
 * - 在自动隐藏模式下（除非被覆盖），根据光标存在情况淡入/淡出停靠栏透明度。
 * - 使用iconHideTimer和FADE_SPEED/HIDE_DELAY常量，如原版。
 */
function autoHideDock() {
    if (!scriptProperties.autoHide || scriptProperties.autoHideOverwrite) {
        // 自动隐藏禁用或在编辑时被覆盖 -> 确保完全可见
        shared.dockAlpha = 1.0;
        iconHideTimer = 0.0;
        return;
    }

    // 检查是否有任何图标检测到光标
    let anyHovered = false;
    for (let i = 0; i < icons.length; i++) {
        const icon = icons[i];
        if (!icon) continue;
        if (icon.cursorDetected) {
            anyHovered = true;
            break;
        }
    }

    // 如果没有事情要做则快速退出（一旦完全隐藏就保持dockAlpha为0）
    if (!anyHovered && iconHideTimer === 0 && shared.dockAlpha === 0) return;

    if (anyHovered) {
        // 重置隐藏计时器并快速淡入
        iconHideTimer = 0.0;
        shared.dockAlpha += (1.0 - shared.dockAlpha) * FADE_SPEED * engine.frametime;
    } else {
        // 无悬停 -> 增加隐藏计时器并在延迟后淡出
        iconHideTimer += engine.frametime;
        if (iconHideTimer >= HIDE_DELAY) {
            shared.dockAlpha += (0.0 - shared.dockAlpha) * FADE_SPEED * engine.frametime;
        }
    }
}

/**
 * 根据totalSpan（图标+间距的总和）和当前模式更新停靠栏背景图层的缩放（thisLayer.scale）。
 * @param {Number} totalSpan - 沿主轴的总像素长度
 */
function updateScale(totalSpan) {
    const minScale = scriptProperties.minScale || 1;
    const extent = (ICON_SIZE * minScale) + (outerSpacing * 2);

    let scaleX = 1;
    let scaleY = 1;

    if (mode === 'horizontal') {
        scaleX = (totalSpan + (outerSpacing * 2)) / BACKGROUND_BASE_WIDTH;
        scaleY = extent / BACKGROUND_BASE_WIDTH;
    } else {
        scaleY = (totalSpan + (outerSpacing * 2)) / BACKGROUND_BASE_WIDTH;
        scaleX = extent / BACKGROUND_BASE_WIDTH;
    }

    thisLayer.scale = new Vec3(scaleX, scaleY, 1);
}

/**
 * 通过名称前缀检测场景中的扩展启动器。
 * @returns {Array<String>} - 以EXTENSION_PREFIX开头的图层名称（扩展）
 */
function detectExtensions() {
    const extensions = [];
    const layerCount = thisScene.getLayerCount();

    for (let i = 0; i < layerCount; i++) {
        const layer = thisScene.getLayer(i);
        if (!layer || typeof layer.name !== 'string') continue;

        // 检测扩展命名约定
        if (layer.name.startsWith(EXTENSION_PREFIX)) {
            extensions.push(layer.name);
        }
    }

    return extensions;
}

function handleIconDragging() {
    // 检查拖拽功能是否启用
    if (!scriptProperties.enableDragging) {
        // 如果拖拽功能被禁用，重置所有拖拽状态
        if (isAnyHeld) {
            isAnyHeld = false;
            draggingIndex = -1;
            gapIndex = -1;
        }
        return;
    }

    const axis = (mode === "horizontal") ? "x" : "y";

    // 查找被拖拽的图标
    let heldIndex = -1;
    for (let i = 0; i < icons.length; i++) {
        if (icons[i] && icons[i].held) { heldIndex = i; break; }
    }

    // 没有被拖拽的 → 完成排序并重置
    if (heldIndex === -1) {
        if (isAnyHeld && draggingIndex !== -1 && gapIndex !== -1) {
            const moved = dockOrder.splice(draggingIndex, 1)[0];
            dockOrder.splice(gapIndex, 0, moved);
            icons = dockOrder.map(n => thisScene.getLayer(n));
            localStorage.set("dockOrder", dockOrder);
        }
        isAnyHeld = false;
        draggingIndex = -1;
        gapIndex = -1;
        return;
    }

    // 开始拖拽 - 在从布局中排除之前捕获初始位置
    if (!isAnyHeld) {
        isAnyHeld = true;
        draggingIndex = heldIndex;
        gapIndex = heldIndex;
        // 立即捕获当前位置
        heldIconWorldPos = icons[draggingIndex].origin;
    }

    const cursor = input.cursorWorldPosition;
    const relativePosition = cursor.subtract(parent.origin);
    // 仅更新拖拽轴
    heldIconWorldPos[axis] = relativePosition[axis];

    const ordered = [];
    for (let i = 0; i < dockOrder.length; i++) {
        if (i === draggingIndex) continue;
        const layer = thisScene.getLayer(dockOrder[i]);
        if (!layer || !layer.visible) continue;
        const s = layer.scale;
        const size = (mode === "horizontal") ? layer.size.x * s.x : layer.size.y * s.y;
        const centerRelative = layer.origin[axis] - thisLayer.origin[axis];
        ordered.push({ i, layer, center: centerRelative, size });
    }

    let newGap = ordered.length;
    for (let i = 0; i < ordered.length; i++) {
        if (relativePosition[axis] < ordered[i].center) { newGap = i; break; }
    }
    gapIndex = newGap;
}

// ==================== 共享启动器函数 ====================
// 封装自 Launcher2.js 的所有功能

// 启动器常量
const LAUNCHER_CLICK_THRESHOLD = 0.33;    // 长按拖拽阈值时间（秒）- 按住图标超过此时间后开始拖拽，小于此时间则视为点击
const LAUNCHER_WIGGLE_SPEED = 16;         // 拖拽时图标摇摆速度
const LAUNCHER_WIGGLE_AMOUNT = 8;         // 拖拽时图标摇摆幅度（角度）
const LAUNCHER_TRANSITION_SPEED = 4;      // 图标动画过渡速度
const LAUNCHER_HELD_INDEX = 512;          // 被拖拽图标的图层排序索引（确保在最上层显示）

/**
 * 角度插值函数
 * @param {Number} a - 起始角度
 * @param {Number} b - 目标角度
 * @param {Number} t - 插值因子
 * @returns {Number} 插值后的角度
 */
function lerpAngle(a, b, t) {
    let delta = (((b - a) % 360) + 360) % 360;
    if (delta > 180) delta -= 360;
    return a + delta * Math.max(Math.min(t, 1), 0);
}

/**
 * 初始化启动器图层
 * @param {ILayer} layer - 图层对象
 * @param {Vec3} value - 初始缩放值
 * @returns {Object} 启动器状态对象
 */
shared.initLauncher = function(layer, value) {
    // 定义图层属性
    Object.defineProperty(layer, "cursorDetected", { enumerable: true, configurable: true, writable: true, value: false });
    Object.defineProperty(layer, "hovered", { enumerable: true, configurable: true, writable: true, value: false });
    Object.defineProperty(layer, "clicked", { enumerable: true, configurable: true, writable: true, value: false });
    Object.defineProperty(layer, "held", { enumerable: true, configurable: true, writable: true, value: false });

    // 获取原始索引和父级
    const originalIndex = thisScene.getLayerIndex(layer);
    const parent = layer.getParent() || layer;

    // 格式化图层名称用于快捷方式
    let layerName = layer.name;
    const formattedName = layerName.toLowerCase().replace(/ /g, '');

    // 设置缩放
    const rawOriginalScale = new Vec3(value.x, value.y, value.z);
    const originalScale = rawOriginalScale.x;

    // 设置角度
    const staticAngle = layer.angles.z;

    // 生成随机相位偏移
    const phaseOffset = Math.random() * Math.PI * 2;

    // 返回状态对象
    return {
        originalScale: originalScale,
        currentScale: originalScale,
        parent: parent,
        formattedName: formattedName,
        pressStartTime: 0,
        isPressing: false,
        staticAngle: staticAngle,
        currentAngle: staticAngle,
        wiggleTime: 0,
        phaseOffset: phaseOffset,
        originalIndex: originalIndex
    };
};

/**
 * 更新启动器图层
 * @param {ILayer} layer - 图层对象
 * @param {Object} state - 启动器状态对象
 * @param {Vec3} value - 当前缩放值
 */
shared.updateLauncher = function(layer, state, value) {
    // 如果停靠栏或图层不可见则跳过逻辑
    if (!state.parent || !state.parent.visible || !layer.visible) {
        return;
    }

    const cursor = shared.cursorWorldPosition;
    const worldPos = state.parent.origin.add(layer.origin);
    const dist = cursor.subtract(worldPos).length();

    layer.cursorDetected = dist <= shared.radius;

    // 处理来自共享淡入淡出控制的透明度
    layer.alpha = shared.dockAlpha;

    // 如果可能的话提前返回
    if (!layer.cursorDetected && layer.alpha == 0) return; // 光标不在范围内且停靠栏被隐藏
    if (!layer.cursorDetected && layer.scale == shared.minScale) return; // 光标不在范围内且图层缩放匹配默认缩放

    // 检查按压持续时间以检测拖拽（仅在拖拽功能启用时）
    if (state.isPressing && !layer.held && scriptProperties.enableDragging) {
        // 计算当前按压持续时间（当前运行时间 - 按压开始时间）
        let pressDuration = engine.runtime - state.pressStartTime;

        // 如果按压时间超过阈值（0.33秒），则开始拖拽模式
        if (pressDuration >= LAUNCHER_CLICK_THRESHOLD) {
            layer.held = true;                              // 标记图标为被拖拽状态
            shared.appDockDragging = true;                  // 设置全局拖拽状态，触发其他图标摇摆效果
            thisScene.sortLayer(layer, LAUNCHER_HELD_INDEX); // 将被拖拽图标移到最上层显示
        }
    }

    let t = (dist - shared.minDistance) / (shared.radius - shared.minDistance);
    t = WEMath.smoothStep(0, 1, t);

    let targetScale = WEMath.mix(shared.maxScale, shared.minScale, t);
    state.currentScale = WEMath.mix(state.currentScale, targetScale, engine.frametime * 18);
    state.currentScale = Math.max(shared.minScale, Math.min(shared.maxScale, state.currentScale));

    // 如果任何图标被拖拽则"摇摆"图层
    const shouldWiggle = shared.appDockDragging;
    let targetAngle;

    if (shouldWiggle) {
        state.wiggleTime += engine.frametime * LAUNCHER_WIGGLE_SPEED;
        const wiggleOffset = Math.sin(state.wiggleTime + state.phaseOffset) * LAUNCHER_WIGGLE_AMOUNT;
        targetAngle = state.staticAngle + wiggleOffset;
    } else {
        targetAngle = state.staticAngle;
        state.wiggleTime = 0;
    }

    layer.scale = new Vec3(state.currentScale, state.currentScale, state.currentScale);

    state.currentAngle = lerpAngle(state.currentAngle, targetAngle, LAUNCHER_TRANSITION_SPEED * engine.frametime);
    layer.angles = new Vec3(0, 0, state.currentAngle);
};

/**
 * 处理启动器光标按下事件
 * @param {ILayer} layer - 图层对象
 * @param {Object} state - 启动器状态对象
 * @param {Object} event - 事件对象
 */
shared.launcherCursorDown = function(layer, state, event) {
    if (layer.visible && state.parent && state.parent.visible) {
        state.isPressing = true;
        state.pressStartTime = engine.runtime;
        layer.clicked = false;
        layer.held = false;
    }
};

/**
 * 处理启动器光标释放事件
 * @param {ILayer} layer - 图层对象
 * @param {Object} state - 启动器状态对象
 * @param {Object} event - 事件对象
 */
shared.launcherCursorUp = function(layer, state, event) {
    if (!layer.visible || !state.parent || !state.parent.visible) {
        return;
    }

    if (state.isPressing) {
        // 计算总按压持续时间
        let pressDuration = engine.runtime - state.pressStartTime;

        // 根据按压时间判断是点击还是拖拽操作
        if (pressDuration < LAUNCHER_CLICK_THRESHOLD) {
            // 按压时间小于0.33秒 → 视为点击操作
            // 特殊处理：如果是扩展图层（以 EXTENSION_PREFIX 开头），不设置 clicked 属性（避免弹跳）
            if (!layer.name || !layer.name.startsWith(EXTENSION_PREFIX)) {
                layer.clicked = true;
                // 确保formattedName不为空再尝试启动应用
                if (state.formattedName && state.formattedName.trim() !== '') {
                    engine.openUserShortcut(state.formattedName);
                }
            }
            // 对于扩展图层，短按不执行任何操作（不弹跳，不启动应用）
        } else {
            // 按压时间大于等于0.33秒 → 视为拖拽操作，结束拖拽状态
            layer.held = false;                              // 取消图标拖拽状态
            shared.appDockDragging = false;                  // 取消全局拖拽状态，停止摇摆效果
            thisScene.sortLayer(layer, state.originalIndex); // 恢复图标原始图层顺序
        }
        state.isPressing = false;
    }
};

/**
 * 专门用于Audio启动器的更新函数 - 无弹跳效果
 * @param {ILayer} layer - 图层对象
 * @param {Object} state - 启动器状态对象
 * @param {Vec3} value - 当前缩放值
 */
shared.updateAudioLauncher = function(layer, state, value) {
    // 如果停靠栏或图层不可见则跳过逻辑
    if (!state.parent || !state.parent.visible || !layer.visible) {
        return value;
    }

    // 处理来自共享淡入淡出控制的透明度
    layer.alpha = shared.dockAlpha;

    // 检查按压持续时间以检测拖拽（对于Audio图层总是启用）
    if (state.isPressing && !layer.held) {
        // 计算当前按压持续时间（当前运行时间 - 按压开始时间）
        let pressDuration = engine.runtime - state.pressStartTime;

        // 如果按压时间超过阈值（0.33秒），则开始拖拽模式
        if (pressDuration >= LAUNCHER_CLICK_THRESHOLD) {
            layer.held = true;                              // 标记图标为被拖拽状态
            shared.appDockDragging = true;                  // 设置全局拖拽状态，触发其他图标摇摆效果
            thisScene.sortLayer(layer, LAUNCHER_HELD_INDEX); // 将被拖拽图标移到最上层显示
        }
    }

    // 完全禁用鼠标悬停检测和弹跳效果 - 始终保持原始缩放
    layer.scale = new Vec3(state.originalScale, state.originalScale, state.originalScale);

    // 如果任何图标被拖拽则"摇摆"图层（保留摇摆效果）
    const shouldWiggle = shared.appDockDragging;
    let targetAngle;

    if (shouldWiggle) {
        state.wiggleTime += engine.frametime * LAUNCHER_WIGGLE_SPEED;
        const wiggleOffset = Math.sin(state.wiggleTime + state.phaseOffset) * LAUNCHER_WIGGLE_AMOUNT;
        targetAngle = state.staticAngle + wiggleOffset;
    } else {
        targetAngle = state.staticAngle;
        state.wiggleTime = 0;
    }

    // 应用角度变化（保留摇摆效果）
    state.currentAngle = lerpAngle(state.currentAngle, targetAngle, LAUNCHER_TRANSITION_SPEED * engine.frametime);
    layer.angles = new Vec3(0, 0, state.currentAngle);

    return value;
};

/**
 * 专门用于Audio启动器的光标释放事件处理函数
 * @param {ILayer} layer - 图层对象
 * @param {Object} state - 启动器状态对象
 * @param {Object} event - 事件对象
 */
shared.audioLauncherCursorUp = function(layer, state, event) {
    if (!layer.visible || !state.parent || !state.parent.visible) {
        return;
    }

    if (state.isPressing) {
        // 计算总按压持续时间
        let pressDuration = engine.runtime - state.pressStartTime;

        if (pressDuration >= LAUNCHER_CLICK_THRESHOLD) {
            // 长按：结束拖拽状态但不启动应用
            shared.appDockDragging = false;
            layer.held = false;
            thisScene.sortLayer(layer, state.originalIndex);
        } else {
            // 短按：不执行任何操作（不启动应用）
            layer.clicked = true; // 标记为点击但不启动应用
        }

        state.isPressing = false;
    }
};

