		label: '',
		value: ''
	})
	.finish();

// Launcher state object
let launcherState;

export function init(value) {
    // Initialize launcher using shared function
    launcherState = shared.initLauncher(thisLayer, value);

    // 重要：覆盖formattedName以使用用户配置的快捷方式
    if (scriptProperties.newText && scriptProperties.newText.trim() !== '') {
        launcherState.formattedName = scriptProperties.newText.trim();
    }
}

export function update(value) {
    // Use shared update function
    return shared.updateLauncher(thisLayer, launcherState, value);
}

