visible.script:
'use strict';
let fonts = [
    null, 
    engine.registerAsset("fonts/Jost-Medium.ttf"),
    engine.registerAsset("fonts/Atami-Regular.otf"),
    engine.registerAsset("fonts/SmileySans-Oblique.ttf"),
    engine.registerAsset("fonts/方正琥珀简体.ttf"),
    engine.registerAsset("fonts/汉仪彩云体简.ttf"),
    engine.registerAsset("fonts/极限新圆.ttf"),
    engine.registerAsset("fonts/Aa后浪行楷.ttf"),
    engine.registerAsset("fonts/chaozishehaoxiashoushujianfan.ttf"),
    engine.registerAsset("fonts/李旭科书法.ttf"),
    engine.registerAsset("fonts/刘欢卡通手书1.07.ttf"),
    engine.registerAsset("fonts/千图笔锋手写体.ttf"),
    engine.registerAsset("fonts/禹卫书法行书简体.ttf"),
    engine.registerAsset("fonts/LEVIBRUSH.ttf"),
    engine.registerAsset("fonts/opentype (1).otf"),
    engine.registerAsset("fonts/Tourner (100).ttf"),
    engine.registerAsset("fonts/Tourner (101).ttf"),
    engine.registerAsset("fonts/Tourner (440).ttf"),
    engine.registerAsset("fonts/Tourner (544).ttf"),
    engine.registerAsset("fonts/Champignon.ttf"),
    engine.registerAsset("fonts/英文字体（书法）.ttf"),
    engine.registerAsset("fonts/SourceHanSans-Heavy.otf"),
    engine.registerAsset("fonts/Imagination Station.ttf"),
    engine.registerAsset("fonts/Aa攒劲小楷.ttf"),
    engine.registerAsset("fonts/白路飞云手写体.ttf"),
    engine.registerAsset("fonts/演示秋鸿楷.ttf"),
    engine.registerAsset("fonts/SF-Pro-Medium.otf"),
    engine.registerAsset("fonts/SF-Pro-Rounded-Heavy.otf"),
    engine.registerAsset("fonts/方正行楷简体.ttf"),
    engine.registerAsset("fonts/书法字体.ttf"),
    engine.registerAsset("fonts/MapleMono-CN-Bold.ttf"),
    engine.registerAsset("fonts/DouyinSansBold.ttf")
];

function setLayerFont(layerName, fontIndex) {
    let layer = thisScene.getLayer(layerName);
    if (layer && fontIndex >= 1 && fontIndex <= 31) {
        layer.font = fonts[fontIndex];
    } 
}

export function applyUserProperties(userProperties) {
    if (userProperties.hasOwnProperty('text1')) {
        setLayerFont('周一', parseInt(userProperties.text1));
        setLayerFont('周二', parseInt(userProperties.text1));
        setLayerFont('周三', parseInt(userProperties.text1));
        setLayerFont('周四', parseInt(userProperties.text1));
        setLayerFont('周五', parseInt(userProperties.text1));
        setLayerFont('周六', parseInt(userProperties.text1));
        setLayerFont('周日', parseInt(userProperties.text1));
        // setLayerFont('年', parseInt(userProperties.text1));
        setLayerFont('月份', parseInt(userProperties.text1));
        setLayerFont('日期', parseInt(userProperties.text1));

    }
    // if (userProperties.hasOwnProperty('text2')) {
    //     setLayerFont('歌手', parseInt(userProperties.text2));
    //     setLayerFont('歌名', parseInt(userProperties.text2));
    // }
    if (userProperties.hasOwnProperty('text3')) {
        setLayerFont('时间表', parseInt(userProperties.text3));
    }
    if (userProperties.hasOwnProperty('text4')) {
        setLayerFont('中文', parseInt(userProperties.text4));
        setLayerFont('英文', parseInt(userProperties.text4));
    }


    if(userProperties.hasOwnProperty('newproperty57')){
        switch(userProperties.newproperty57){
            case("1"):
            thisScene.getLayer('中文').colorBlendMode = 0
            thisScene.getLayer('英文').colorBlendMode = 0
            break;
            case("2"):
            thisScene.getLayer('中文').colorBlendMode = 11
            thisScene.getLayer('英文').colorBlendMode = 11
            break;
        }
    }  

    if(userProperties.hasOwnProperty('newproperty71')){

        if(userProperties.newproperty71 == 1){
            thisScene.getLayer('时间表').colorBlendMode = 0
        }else if(userProperties.newproperty71 == 2){
            thisScene.getLayer('时间表').colorBlendMode = 11
        }

    } 

    if(userProperties.hasOwnProperty('newproperty50')){

        if(userProperties.newproperty50 == 1){
            thisScene.getLayer('音频').colorBlendMode = 0
        }else if(userProperties.newproperty71 == 2){
            thisScene.getLayer('音频').colorBlendMode = 11
        }

    } 

    // //日历透明度  判断不等于1 关闭阴影
    // if(userProperties.hasOwnProperty('newproperty73')){
    //     if(userProperties.newproperty73 == 1){
    //         thisScene.getLayer('日历阴影').visible = true
    //     }else{
    //         thisScene.getLayer('日历阴影').visible = false
    //     }
    // }
    // //播放器透明度
    // if(userProperties.hasOwnProperty('newproperty74')){
    //     if(userProperties.newproperty74 == 1){
    //         thisScene.getLayer('音乐阴影').visible = true
    //     }else{
    //         thisScene.getLayer('音乐阴影').visible = false
    //     }
    // }




}
